head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vScrenTpCD = "";
// 세션정보를 얻기위한 함수사용
scwin.fn_GetPar, scwin.fn_SetPar, scwin.fr_SecuGrpId;
scwin.pIndex;
scwin.TR_JOB;
scwin.vIsurCd, scwin.vIsurNm, scwin.vInputRnd, scwin.vTrJob;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.pIndex = $c.stf.getQuery(frame.srcUrl, "nIndex");
        const sbmOptions = {
            id : "sbm_dts_Item",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_Item=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        dts_Item.insertRow();
        let parentWin = $c.frame.path("../");
        scwin.vIsurCd = parentWin.gIsurCd;
        scwin.vIsurNm = parentWin.gIsurNm;
        scwin.vInputRnd = parentWin.gInputRnd;
        scwin.vTrJob = parentWin.gGubnStat;
        if (scwin.vTrJob === "U") {
            // alert("vIsurCd:"+vIsurCd + " vIsurNm:"+vIsurNm+" vInputRnd:"+vInputRnd+" vTrJob:"+vTrJob);
            txb_ISUR_CD.setValue(scwin.vIsurCd);
            txb_COM_NM.setValue(scwin.vIsurNm);
            txb_ISUR_CD.setReadOnly(true);
            img_COM_NM.setBackgroundImage("../img/btn_search_d.gif");
            img_COM_NM.setDisabled(true);
            btn_save.setBackgroundImage("../img/btn_save_d.gif");
            btn_save.setDisabled(true);
            await scwin.readSync();
        } else {
            // I
            scwin.vIsurCd = "";
            scwin.vIsurNm = "";
            scwin.vInputRnd = "";
            btn_update.setBackgroundImage("../img/btn_modify_d.gif");
            btn_update.setDisabled(true);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05962.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_COM_NM_onclick
 * @description img_COM_NM 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_COM_NM_onclick = function() {
    try {
        scwin.fn_GetPar = scwin.getParIsur;
        scwin.fn_SetPar = scwin.setParIsur;
        $c.lc.fn_PopFindCorpChrg(scwin.fr_SecuGrpId);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05962.img_COM_NM_onclick" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05962.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name btn_save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_save_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05962.btn_save_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05962.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        await scwin.parentRefresh();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05962.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        $c.lc.fn_alertMsg('F');
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05962.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name btn_DESIGN_DD_1_onclick
 * @description btn_DESIGN_DD_1 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_DESIGN_DD_1_onclick = function() {
    try {
        popUpCalendar2(edt_DESIGN_DD_1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05962.btn_DESIGN_DD_1_onclick" });
    }
};

/**
 * @method
 * @name btn_update_onclick
 * @description 「수정」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_update_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05962.btn_update_onclick" });
    }
};

/**
 * @method
 * @name btn_delete_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_delete_onclick = async function() {
    try {
        await scwin.delete();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05962.btn_delete_onclick" });
    }
};

/**
 * @method
 * @name trs_Delete_OnSuccess
 * @description Delete On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Delete_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
        let parentWin = $c.frame.path("../");
        parentWin.fn_list_sync();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05962.trs_Delete_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Delete_OnFail
 * @description Delete On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Delete_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제"));
        await $c.win.alert(trs_Delete.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05962.trs_Delete_OnFail" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name readSync
 * @description read Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readSync = async function() {
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral&outputMessageId=HDNCHAMP_MGM_INOUT";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&queryId=lds.stf.lstproc.hdnchamp.select";
    url += "&{P}param01=" + scwin.vIsurCd;
    url += "&{P}param02=" + scwin.vInputRnd;
    const sbmOptions = {
        id : "sbm_dts_Item",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Item=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name trs
 * @description trs 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function() {
    scwin.setValue();
    scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    trs_Save.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/SectionTypeChange.do",
        ref : "dts_Item",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    const rtn = confirm('삭제 하시겠습니까?');
    if (rtn === 1) {

        // dts_Del.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
        dts_Del.insertRow();
        dts_Del.setCellData(1, "ISUR_CD", txb_ISUR_CD.getValue());
        dts_Del.setCellData(1, "INPUT_RND", scwin.vInputRnd);
        dts_Del.setCellData(1, "REG_ID", js_emp_no);
        const sbmOptions = {
            id : "sbm_trs_Delete",
            action : "/SectionTypeChange.do",
            ref : "dts_Del",
            target : "trs_Delete=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsur
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_ISUR_CD.getValue(); // 발행기관코드값
    arrPar[1] = txb_COM_NM.getValue(); // 발행기관명
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤
    arrPar[3] = "9"; // 회사코드팝업 전체데이터
    return arrPar.length;
};

/**
 * @method
 * @name setParIsur
 * @description set Par Isur 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsur = function(arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_COM_NM.setValue(arrPar[0].COM_NM);
    }
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (txb_ISUR_CD.getValue() === "") {
        await $c.win.alert("[회사명]를 입력하세요.");
        txb_ISUR_CD.focus();
        return false;
    }
    if (txb_SECT_AHTH_QUAL_CONTN.getValue() === "") {
        await $c.win.alert("[라이징스타 인증자격]을 입력하세요.");
        txb_SECT_AHTH_QUAL_CONTN.focus();
        return false;
    }
    if (txb_SECT_AHTH_INST_NM.getValue() === "") {
        await $c.win.alert("[라이징스타 인증기관]을 입력하세요.");
        txb_SECT_AHTH_INST_NM.focus();
        return false;
    }
    if (edt_DESIGN_DD_1.getValue() === "") {
        await $c.win.alert("[라이징스타 지정일자]를 입력하세요.");
        edt_DESIGN_DD_1.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name setValue
 * @description set Value 처리
 * @returns {void}
 * @hidden N
 */
scwin.setValue = function() {
    dts_Item.setCellData(1, "PINDEX", scwin.pIndex);
    dts_Item.setCellData(1, "ISUR_CD", txb_ISUR_CD.getValue());
    dts_Item.setCellData(1, "INPUT_RND", scwin.vInputRnd);
    dts_Item.setCellData(1, "SECT_AHTH_QUAL_CONTN", txb_SECT_AHTH_QUAL_CONTN.getValue());
    dts_Item.setCellData(1, "SECT_AHTH_INST_NM", txb_SECT_AHTH_INST_NM.getValue());
    /*	dts_Item.setNameValue(1, "RESRH_DEV_INVST_RTO",getObjectValue(txb_RESRH_DEV_INVST_RTO))        ;
    dts_Item.setNameValue(1, "ACNTG_CORP_REVW_CONTN",getObjectValue(txb_ACNTG_CORP_REVW_CONTN)) ;
    dts_Item.setNameValue(1, "PRSNT_SECT_DESIGN_DD",getObjectValue(edt_PRSNT_SECT_DESIGN_DD))      ;
    dts_Item.setNameValue(1, "SECT_AHTH_CONTN",getObjectValue(txb_SECT_AHTH_CONTN))               ;*/
    dts_Item.setCellData(1, "DESIGN_DD_1", edt_DESIGN_DD_1.getValue());
    dts_Item.setCellData(1, "REMK_1", txa_REMK_1.getValue());
    dts_Item.setCellData(1, "REG_ID", js_emp_no);
};

/**
     * @method
     * @name save
     * @description save 처리
     * @returns {Promise<void>}
     * @hidden N
     */
scwin.save = async function() {
    scwin.TR_JOB = scwin.vTrJob;
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        // dts_Item.UserStatus(1) = TB_JOB_INSERT;
        await scwin.trs();
    }
};

/**
 * @method
 * @name parentRefresh
 * @description parent Refresh 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.parentRefresh = async function() {
    const fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
    await $c.win.closePopup();
};
